	// Start of user code block custom items
	// End of user code block custom items
	private static RegistryObject<Item> block(RegistryObject<Block> block) {
		return block(block, new Item.Properties());
	}

	private static RegistryObject<Item> block(RegistryObject<Block> block, Item.Properties properties) {
		return REGISTRY.register(block.getId().getPath(), () -> new BlockItem(block.get(), properties));
	}

	@SubscribeEvent
	public static void clientLoad(FMLClientSetupEvent event) {
		event.enqueueWork(() -> {
			ItemProperties.register(SPONGE.get(), ResourceLocation.parse("butchery:sponge_wetness"), (itemStackToRender, clientWorld, entity, itemEntityId) -> (float) SpongepropertyvalueproviderProcedure.execute(itemStackToRender));
			ItemProperties.register(RAG.get(), ResourceLocation.parse("butchery:rag_wetness"), (itemStackToRender, clientWorld, entity, itemEntityId) -> (float) RagpropertyvalueproviderProcedure.execute(itemStackToRender));
			ItemProperties.register(RAW_SILVERFISH_CHUNKS.get(), ResourceLocation.parse("butchery:raw_silverfish_chunks_multiple"),
					(itemStackToRender, clientWorld, entity, itemEntityId) -> (float) RawsilverfishchunksPropertyValueProviderProcedure.execute(itemStackToRender));
			ItemProperties.register(COOKED_SILVERFISH_CHUNKS.get(), ResourceLocation.parse("butchery:cooked_silverfish_chunks_multiple"),
					(itemStackToRender, clientWorld, entity, itemEntityId) -> (float) RawsilverfishchunksPropertyValueProviderProcedure.execute(itemStackToRender));
			ItemProperties.register(SLIME_CHUNKS.get(), ResourceLocation.parse("butchery:slime_chunks_multiple"),
					(itemStackToRender, clientWorld, entity, itemEntityId) -> (float) RawslimechunksPropertyValueProviderProcedure.execute(itemStackToRender));
			ItemProperties.register(MAGMA_CHUNKS.get(), ResourceLocation.parse("butchery:magma_chunks_multiple"), (itemStackToRender, clientWorld, entity, itemEntityId) -> (float) MagmachunksPropertyValueProviderProcedure.execute(itemStackToRender));
			ItemProperties.register(COIN.get(), ResourceLocation.parse("butchery:coin_amount"), (itemStackToRender, clientWorld, entity, itemEntityId) -> (float) CoinpropertyvalueproviderProcedure.execute(itemStackToRender));
			ItemProperties.register(RAW_ENDERMITE_CHUNKS.get(), ResourceLocation.parse("butchery:raw_endermite_chunks_multiple"),
					(itemStackToRender, clientWorld, entity, itemEntityId) -> (float) RawendermitechunksPropertyValueProviderProcedure.execute(itemStackToRender));
			ItemProperties.register(COOKED_ENDERMITE_CHUNKS.get(), ResourceLocation.parse("butchery:cooked_endermite_chunks_multiple"),
					(itemStackToRender, clientWorld, entity, itemEntityId) -> (float) RawendermitechunksPropertyValueProviderProcedure.execute(itemStackToRender));
		});
	}
